# test_netgen.py
import unittest                                     # The unittest module is imported to create a test case for the generate_interface_config function. This module provides a framework for writing and running tests in Python.
from netgen import generate_interface_config        # The generate_interface_config function is imported from the netgen module. This function will be tested to ensure that it generates the correct network interface configuration based on the provided input data.

class TestNetgen(unittest.TestCase):                # The TestNetgen class is defined as a subclass of unittest.TestCase. This class will contain test methods to test the functionality of the generate_interface_config function. By inheriting from unittest.TestCase, the TestNetgen class gains access to various assertion methods and test-running capabilities provided by the unittest framework.
    def test_generate_interface_config(self):       # The test_generate_interface_config method is defined to test the generate_interface_config function. This method will create input data representing a network interface, define the expected output configuration, call the generate_interface_config function with the input data, and assert that the actual output matches the expected output.
        input_data = {                              # The input_data dictionary is defined to represent a network interface with the following attributes: name, description, ip_address, and subnet_mask. This dictionary will be passed as an argument to the generate_interface_config function to generate the corresponding network interface configuration.
            "name": "GigabitEthernet0/1",
            "description": "Uplink to core switch",
            "ip_address": "10.0.0.1",
            "subnet_mask": "255.255.255.0"
        }

        expected_output = (                         # The expected_output variable is defined as a string representing the expected network interface configuration that should be generated by the generate_interface_config function when provided with the input_data. This string includes the interface name, description, IP address, subnet mask, and a "no shutdown" command.
            "interface GigabitEthernet0/1\n"
            " description Uplink to core switch\n"
            " ip address 10.0.0.1 255.255.255.0\n"
            " no shutdown"
        )

        actual_output = generate_interface_config(input_data)       # The generate_interface_config function is called with the input_data dictionary as an argument. The function generates the network interface configuration based on the provided input data, and the resulting configuration string is stored in the actual_output variable.
        self.assertEqual(actual_output, expected_output)            # The assertEqual method of the unittest.TestCase class is called to compare the actual_output generated by the generate_interface_config function with the expected_output. If the two strings are equal, the test passes; otherwise, an AssertionError is raised, indicating that the test has failed.

if __name__ == '__main__':                                          # The if __name__ == '__main__': block is used to check if the script is being run directly (as opposed to being imported as a module). If the script is run directly, the unittest.main() function is called to execute the test case defined in the TestNetgen class. This allows the test to be run from the command line or an IDE.
    unittest.main()                                                 # The unittest.main() function is called to run the test case defined in the TestNetgen class. This function discovers and runs all test methods in the class, providing output on the test results, including which tests passed or failed.
